import{_ as o,o as u,c as q,ag as r}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"08 · 民俗志怪知识库——从 14 部天涯神贴里提取的可用知识","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/handbook/08_民俗志怪知识库.md","filePath":"topics/tianya/handbook/08_民俗志怪知识库.md"}'),d={name:"topics/tianya/handbook/08_民俗志怪知识库.md"};function n(s,t,a,g,l,i){return u(),q("div",null,[...t[0]||(t[0]=[r('<h1 id="_08-·-民俗志怪知识库——从-14-部天涯神贴里提取的可用知识" tabindex="-1">08 · 民俗志怪知识库——从 14 部天涯神贴里提取的可用知识 <a class="header-anchor" href="#_08-·-民俗志怪知识库——从-14-部天涯神贴里提取的可用知识" aria-label="Permalink to &quot;08 · 民俗志怪知识库——从 14 部天涯神贴里提取的可用知识&quot;">​</a></h1><blockquote><p><strong>材料与方法</strong>：本库基于 /tmp/thunder/texts/ 天涯神贴文本精读整理，逐条标注出处帖号（文件名前缀即帖号）。每条知识给出<strong>成色判断</strong>，分三档： 【行业·真实】＝可查证的现实行业知识、制度或文献记载； 【民俗·传说】＝民间流传的信仰体系，有文献与口传，无实证机制； 【小说·演绎】＝作者借真实知识骨架虚构的设定，只可入文，不可当真。 任务点名的若干条目（赶尸、七星旋扣、考古规矩、骗术门类）实际藏于同库相邻帖（帖 110、141、17 等），已按真实出处标注。</p></blockquote><hr><h2 id="a-民俗与行业知识本体" tabindex="-1">A. 民俗与行业知识本体 <a class="header-anchor" href="#a-民俗与行业知识本体" aria-label="Permalink to &quot;A. 民俗与行业知识本体&quot;">​</a></h2><h3 id="a1-棺椁制度与殡葬工艺-帖-110" tabindex="-1">A1. 棺椁制度与殡葬工艺（帖 110） <a class="header-anchor" href="#a1-棺椁制度与殡葬工艺-帖-110" aria-label="Permalink to &quot;A1. 棺椁制度与殡葬工艺（帖 110）&quot;">​</a></h3><ul><li><strong>棺与椁的区别</strong>：&quot;棺是装死人的，而椁是套在棺外面的，一般用来放殉葬品。&quot;椁与棺之间的夹层可用来填塞冰块防腐——帖 110 开篇那口&quot;套椁大棺&quot;，夹层里就是浮冰，故尸体&quot;没有起黑点，也没有腐臭&quot;。</li><li><strong>墨斗线与七星旋扣</strong>：出殡时棺盖上覆黄帛（写往生祷文），以墨斗线压帛垂直捆住棺身；捆棺的打结法行内叫<strong>七星旋扣</strong>，&quot;只有干我们这一行的业内人士才懂&quot;，帖中两单生意都靠&quot;结法不对&quot;识破棺材被动过手脚。</li><li><strong>缝尸手艺</strong>：有斩刑的年代，处决犯人下葬前要用针线把头颅缝回脖颈；民国改枪决后基本绝迹，但帖中殡葬师两年前还接过车祸亡者&quot;一针一针缝回去&quot;的活——颈部一圈细密针脚是分辨&quot;头是不是原装&quot;的关键物证。</li><li><strong>行内禁忌</strong>：不得脱殓（&quot;这种行为已经算是猥亵尸体，在我们行内是绝对不允许的&quot;）；遇尸体睁眼等异状，须立刻磕头赔罪&quot;赔罪&quot;后再合目；接活先道吉利话（帖名即&quot;见谁都得先说句升官发财&quot;）。</li><li><strong>成色</strong>：棺椁形制、缝尸、冰棺防腐＝【行业·真实】（可与文献棺椁制度互证）；墨斗线七星旋扣＝【民俗·传说】（墨斗辟邪是鲁班匠作民俗，此结法为行内口传）；行规禁忌＝【行业·真实】为主的真实职业伦理。</li></ul><h3 id="a2-湘西赶尸与辰州符体系-帖-110-帖-206-互证" tabindex="-1">A2. 湘西赶尸与辰州符体系（帖 110，帖 206 互证） <a class="header-anchor" href="#a2-湘西赶尸与辰州符体系-帖-110-帖-206-互证" aria-label="Permalink to &quot;A2. 湘西赶尸与辰州符体系（帖 110，帖 206 互证）&quot;">​</a></h3><ul><li><strong>名目</strong>：赶尸在殡葬行内又称<strong>移灵、走影、走尸</strong>，&quot;以湘西一派最为名声卓著&quot;，职业功能是送客死异乡者归故里。</li><li><strong>行头与仪轨</strong>：赶尸匠<strong>不打灯笼</strong>，一手敲小阴锣、一手摇摄魂铃——作用是令夜行人回避、通知沿途关狗；多具尸体&quot;用草绳串起来，每隔七八尺一个&quot;，夜行昼伏。</li><li><strong>核心法门（三十六功法之关键）</strong>：让尸体走起来分两步。第一步封七魄：将朱砂置于死者<strong>脑门心、背膛心、胸膛心窝、左右手板心、脚掌心</strong>七处——&quot;此七处是七窍出入之所&quot;，每处以一道神符压住、五色布条绑紧；第二步锁三魂：将朱砂塞入<strong>耳、鼻、口</strong>并以神符堵紧——&quot;耳、鼻、口乃三魂出入之所&quot;。辰州砂与辰州符是湘西派最被推崇的朱砂与神符（帖 206 亦写&quot;此乃辰州砂，克制阴性物[质]&quot;，两帖互证）。</li><li><strong>变通之术</strong>：帖中主角无朱砂神符时，改用<strong>定针法</strong>——&quot;以定针封住尸体关窍，尸体就得乖乖躺下&quot;，本为对付诈尸之术，反用为起尸。</li><li><strong>成色</strong>：赶尸作为&quot;运尸归乡&quot;的行业（实为双人扛尸、前后配合的夜行运尸术）在民俗学与湘地口述史中有大量记载，仪轨描述属【民俗·传说】；&quot;七窍封魄/三魂出入&quot;的生理学解释是巫道理论，【民俗·传说】；辰州符辰州砂是真实地方物产名（辰砂即朱砂），其&quot;克阴&quot;功效属【民俗·传说】；帖中用定针起尸查&quot;生气流向&quot;则是【小说·演绎】。</li></ul><h3 id="a3-北斗七镇-封魂阵与钉魂-帖-110、帖-24" tabindex="-1">A3. 北斗七镇：封魂阵与钉魂（帖 110、帖 24） <a class="header-anchor" href="#a3-北斗七镇-封魂阵与钉魂-帖-110、帖-24" aria-label="Permalink to &quot;A3. 北斗七镇：封魂阵与钉魂（帖 110、帖 24）&quot;">​</a></h3><ul><li><strong>七星封魂阵</strong>（帖 110）：原理是&quot;用观星之法，找到此地的地脉七关&quot;，再以<strong>三十六枚通魅</strong>按北斗七星方位布下，可困人、镇物；布阵所用钉子&quot;都是有讲究的，这叫做<strong>七星钉魂</strong>&quot;。</li><li><strong>七星阵</strong>（帖 24）：以**七根铜锭（钉）**钉入人身构成的禁阵，民调局反派用其制服吴仁荻；阵成后&quot;就算巫祖重生，也出不去这天台&quot;。</li><li><strong>底层的民俗观念</strong>：北斗主杀伐、镇百邪；以七星对应地脉关窍是风水&quot;寻龙点穴&quot;观念的延伸。</li><li><strong>成色</strong>：北斗镇邪＝【民俗·传说】；具体阵图、三十六通魅、铜锭禁阵均为【小说·演绎】。</li></ul><h3 id="a4-木工厌胜-帖-121" tabindex="-1">A4. 木工厌胜（帖 121） <a class="header-anchor" href="#a4-木工厌胜-帖-121" aria-label="Permalink to &quot;A4. 木工厌胜（帖 121）&quot;">​</a></h3><ul><li><strong>厌胜</strong>：古代工匠行业最著名的禁忌——木匠、石匠在主家房屋的梁、柱、桃符等构件中暗埋物件（人或物之象征），可行厌胜之术：或咒主家败亡，或暗佑宅邸。帖 121 中厌胜门弟子郑国彬自述：《厌胜经》&quot;是不祥之书，凡是拿了它，学[全里面法子的]……&quot;门中弟子多死于同门仇杀；化解之法是找到厌胜物、赔罪拆除，主家甚至可&quot;以厌胜反咒&quot;工匠。</li><li><strong>历史对应</strong>：厌胜术见于史载（汉代巫蛊之祸即宫中埋偶厌胜），匠作《鲁班经》中确有&quot;解厌胜&quot;条目，明清民间&quot;木匠藏符&quot;传说极盛。</li><li><strong>成色</strong>：厌胜＝【民俗·传说】且有历史文献支撑（真实存在的巫术概念）；&quot;厌胜门&quot;组织与《厌胜经》＝【小说·演绎】。</li></ul><h3 id="a5-相术体系-帖-121" tabindex="-1">A5. 相术体系（帖 121） <a class="header-anchor" href="#a5-相术体系-帖-121" aria-label="Permalink to &quot;A5. 相术体系（帖 121）&quot;">​</a></h3><ul><li><strong>断例术语</strong>：帖中老爹解释&quot;<strong>华盖覆面</strong>是额头发乌，<strong>赤虹贯睛</strong>是眼中血丝贯穿黑白眼球&quot;，合断&quot;七日之内有灾&quot;——相术把气色分部位对应吉凶；他还留下可操作的自辩：&quot;看那桥头的大树距离配房太近，却外强中干，知道树心已经空了&quot;——把&quot;相&quot;落到物理观察上，是江湖相师的话术骨架。</li><li><strong>典籍与功法</strong>：家传《麻衣相法》（真实古籍）与祖写《义山公录》（虚构）；童子功&quot;<strong>六相全功</strong>&quot;，腿法绝技&quot;<strong>七星步</strong>，步步按星&quot;踏北斗位。</li><li><strong>成色</strong>：《麻衣相法》、气色术语＝【行业·真实】（真实存在的相术典籍与行话，断效当然无据）；六相全功、七星步＝【小说·演绎】。</li></ul><h3 id="a6-中医知识与《青囊经》典故-帖-119、142、146" tabindex="-1">A6. 中医知识与《青囊经》典故（帖 119、142、146） <a class="header-anchor" href="#a6-中医知识与《青囊经》典故-帖-119、142、146" aria-label="Permalink to &quot;A6. 中医知识与《青囊经》典故（帖 119、142、146）&quot;">​</a></h3><ul><li><strong>青囊典故</strong>：华佗狱中把毕生医术著成《青囊经》交与狱卒，欲传后世，狱卒妻怕丈夫学医失饭计而<strong>焚书</strong>——帖 119 全书的&quot;麦高芬&quot;就是这个&quot;焚而未尽&quot;的半部经。这是三国正史注引（《后汉书·华佗传》医书一卷&quot;青囊书&quot;）演化出的著名传说。</li><li><strong>经中药理</strong>：帖 119 反复强调《青囊经》方剂的特点——&quot;主药只须用一味，而且药引子非[凡]&quot;，药引用人中黄、毛发、胞衣之类；麻沸散以曼陀罗花入药。<strong>成色</strong>：单方重药引是中医真实配伍观念（药引引经报使）；麻沸散含曼陀罗是主流考证；具体方剂与&quot;治鬼胎&quot;&quot;冰人&quot;等功效＝【小说·演绎】。</li><li><strong>尸气与金井（帖 119）</strong>：迁坟开棺最怕尸气，分<strong>灰、黑、红</strong>三色，&quot;最可怕的是红色的尸气，沾上就没救了&quot;；尸气产生机制写为尸体有机质败解有毒气体（黑），唯红色尸气极罕见；破解之物是寄生腐尸的白色真菌&quot;<strong>白陀须</strong>&quot;，恰为红尸气克星。<strong>金井术</strong>：&quot;金井！穴之魂&quot;——高明风水师在穴心设井，内藏墓主生前珍宝以聚地气，是&quot;极厉害的风水师才懂&quot;的秘葬法。<strong>成色</strong>：棺中气体致病（沼气、尸胺）＝【行业·真实】的民俗化表达；红尸气、白陀须＝【小说·演绎】；金井＝【民俗·传说】（陵墓考古中确有&quot;金井&quot;一词，多指穴心定位坑，藏宝说为演绎）。</li><li><strong>断死期（帖 146）</strong>：宜昌名医魏瞎子&quot;单凭声音就能[断人生死]&quot;，病人进门说话，他听完号脉即开药，撂下&quot;你喝也行，不喝也行，自己好自为之&quot;——不收钱即是判了死期。文中指出其法本：《内经·素问》&quot;有很多章节的内容是断病人死[期]&quot;，&quot;有的是凭人的面色而定，有的是诊断周详才定&quot;。<strong>成色</strong>：《素问》确有判断死候的篇章（&quot;真藏脉见者死&quot;等）＝【行业·真实】；凭声断死＝技艺传说【民俗·传说】。</li><li><strong>药材注释（帖 142）</strong>：帖 142 把中药功效直接标注在括号里——麝香[开窍醒神]、橘皮[理气]、何首乌[补血]；连人物都以药命名（木雕匠&quot;白术&quot;、教授&quot;石斛子&quot;），是&quot;上医医国，中医医人，下医医病&quot;（语出《国语·晋语》医和论&quot;上医医国&quot;）的现代童话化用。<strong>成色</strong>：药效注释＝【行业·真实】；辉光修行体系＝【小说·演绎】。</li></ul><h3 id="a7-贼道江湖-春典、赶蛋与老荣-帖-117、26、17" tabindex="-1">A7. 贼道江湖：春典、赶蛋与老荣（帖 117、26、17） <a class="header-anchor" href="#a7-贼道江湖-春典、赶蛋与老荣-帖-117、26、17" aria-label="Permalink to &quot;A7. 贼道江湖：春典、赶蛋与老荣（帖 117、26、17）&quot;">​</a></h3><ul><li><strong>春典（江湖黑话）</strong>（帖 117）：&quot;江湖有谚语：<strong>宁赠一锭金，不教一句春</strong>。&quot;行内互称&quot;老合&quot;，头目叫&quot;瓢把子&quot;，徒弟叫&quot;孩儿们&quot;，行窃铁筷叫&quot;夹手&quot;，棘手叫&quot;扎手&quot;；见面要对春点口令：&quot;青山八字开。&quot;&quot;绿水两边流。&quot;&quot;山在水在桃花开。&quot;&quot;云散雾散贵人来。&quot;&quot;江湖一把伞，许吃不许攒。&quot;&quot;江湖一盏灯，只照夜行客。&quot;——一问一答报字号（&quot;宁国府一枝桃&quot;）。<strong>成色</strong>：春典（唇典）是明清至民国真实存在的江湖行话体系，曲艺、评书文献记载极多＝【行业·真实】；&quot;一枝桃&quot;等字号为【小说·演绎】。</li><li><strong>赶蛋</strong>（帖 117）：盗窃行出师礼——徒弟想自立门户，须向师父申请，在最长一个月内从师父家&quot;盗取一件值钱的东西，然后销声匿迹&quot;；师父若在同期限内抓不到徒弟，赶蛋成功、徒弟另立门户，反之遭殴打烙记、终生居末位。帖中滕雨以二十九天挖地道、藏水塘、噙芦管换气、火烧柴房调虎离山，甚至以&quot;一路上没有印记&quot;反向锁定追踪者的判断（帖 117 开篇），是&quot;赶蛋&quot;的教科书式演绎。<strong>成色</strong>：师徒考核规矩类民间行帮确有类似传统（&quot;踩盘子&quot;&quot;放偷&quot;传说），具体规程＝【民俗·传说】。</li><li><strong>贼行&quot;老荣&quot;</strong>（帖 17、117）：帖 17 论贼行外貌：&quot;老荣都是其貌不扬，不会给人留下深刻印象……老荣从不会和你对视，老荣的眼睛总是飞快地掠过，然后低着头斜着眼看你。&quot;帖 117 又记行规：&quot;丐帮和老荣自古井水不犯河水。&quot;<strong>成色</strong>：老荣为真实江湖切口（指窃贼），特征描述符合扒窃反侦察常识＝【行业·真实】与【民俗·传说】之间。</li><li><strong>五行贼王（帖 26）</strong>：清宫地宫藏&quot;<strong>五行至尊圣王鼎</strong>&quot;——&quot;得此鼎者，得天下，失此鼎者，失天下。此鼎又分五行，称之为金涅、木广、水灵、火煞、土盘&quot;，以龙嘴五灯明灭示国运，由金木水火土五大贼王世家世代看管；&quot;水妖儿克火小邪&quot;把&quot;水克火&quot;做成了性格与感情线。开帖重犯火严当众褪尽锁链丢下&quot;<strong>盗，亦有道</strong>&quot;，立起贼行的道德世界。<strong>成色</strong>：圣王鼎、五行世家＝【小说·演绎】；&quot;盗亦有道&quot;语出《庄子》＝【行业·真实】的典源。</li></ul><h3 id="a8-江湖八大门与骗术门类-帖-17" tabindex="-1">A8. 江湖八大门与骗术门类（帖 17） <a class="header-anchor" href="#a8-江湖八大门与骗术门类-帖-17" aria-label="Permalink to &quot;A8. 江湖八大门与骗术门类（帖 17）&quot;">​</a></h3><ul><li><strong>八大门</strong>：帖 17 作者自注：&quot;江湖八大门在民国时期非常流行，现在仅剩下……三门。&quot;并交代前三章的门类对应：<strong>飘门</strong>（马戏杂技卖艺）、<strong>惊门</strong>（江相派，算命测字诈骗）、<strong>册门</strong>（做旧行，卖假古董假字画——帖中&quot;八大山人&quot;假画局即册门手法：作旧纸张、伪造印章、双簧托儿）。另有<strong>拆白党</strong>（以美色诈骗财物）在帖中出现。</li><li><strong>方法论亮点</strong>：册门做局讲究&quot;取旧换新&quot;——以廉价新仿品与山民换真古玩，再转卖识货者，一层新账一层旧账，赃物链条洗白。</li><li><strong>成色</strong>：八大门分类与江相派＝【行业·真实】（民国江湖行当史有记载）；具体骗局情节＝【小说·演绎】。按：民间另传&quot;蜂麻燕雀&quot;四门骗术，与本库文本所用&quot;八大门&quot;是同一江湖分类学的不同流派说法，文本以八大门为准。</li></ul><h3 id="a9-盗墓与考古的规矩-帖-141-帖-132" tabindex="-1">A9. 盗墓与考古的规矩（帖 141，帖 132） <a class="header-anchor" href="#a9-盗墓与考古的规矩-帖-141-帖-132" aria-label="Permalink to &quot;A9. 盗墓与考古的规矩（帖 141，帖 132）&quot;">​</a></h3><ul><li><strong>装备史（帖 141）</strong>：&quot;老鼠衣&quot;——地下作业连体服，&quot;上面有各种皮套携带各种装备，据说这东西原本是盗墓贼发明的……就和洛阳铲一样被确认为了官方也使用了&quot;：盗墓技术被考古行业收编的两个经典例子。另写地下探测用<strong>地质检波器</strong>：&quot;放射电磁波，凭借从地下回弹的电磁波波形判断地下是否有空洞&quot;。</li><li><strong>墓深与审批（帖 141）</strong>：作者自注其父 80 年代受奉节县文物局邀请勘测——&quot;汉墓的深度较深（一般都在二十米以上，很难直接挖掘）&quot;；奉节探得地下 22 米处约 7-8 立方米空隙，疑为刘备墓（刘备卒于白帝城，夏季高温无法运尸，就地安葬可能性高），&quot;奉节博物馆立即上报了国务院申请开挖，但没有批准。随着三峡蓄水，此处已经永埋水下&quot;。——考古发掘审批权在国务院，未经批准不得主动发掘帝陵级遗存，这是真实的制度。</li><li><strong>现场流程（帖 141）</strong>：发现遗存→&quot;立即通知的县文物局，文物局的人清理后发现&quot;→&quot;省里立即派驻直属考古队来此进行发掘&quot;→抢救性发掘；对抗手段也写实：盗墓贼&quot;从另外一个入口灌进去，淹掉了考古队发现的入口&quot;。</li><li><strong>志怪设定（帖 141）</strong>：僵尸分级制，最高&quot;第六级&quot;称魔王——&quot;和人的外表已经没有任何区别，可以开宗立派，占山为王&quot;，作者甚至给项羽&quot;重瞳&quot;（《史记》明载；并附重瞳者七人：仓颉、虞舜、项羽、吕光、鱼俱罗、李煜、高洋）安上此说。帖 132 则以&quot;簋心风水陵&quot;、四象（老阴老阳少阴少阳）方位、祭祀杀人数字规律（塔吊三死、钢水三死、蓄水池死者数字暗合仪式）构成&quot;风水陵—献祭&quot;的暗黑机关学。</li><li><strong>成色</strong>：洛阳铲、老鼠衣、物探、审批流程、抢救性发掘＝【行业·真实】；僵尸分级、&quot;古代异常事件调查科&quot;＝【小说·演绎】；帖 132 的风水机关学＝【民俗·传说】骨架上的【小说·演绎】。</li></ul><h3 id="a10-死刑犯的最后时光-帖-136" tabindex="-1">A10. 死刑犯的最后时光（帖 136） <a class="header-anchor" href="#a10-死刑犯的最后时光-帖-136" aria-label="Permalink to &quot;A10. 死刑犯的最后时光（帖 136）&quot;">​</a></h3><ul><li><strong>羁押制度</strong>：作者答疑明写：&quot;以前看守所都是不把死刑犯和普通犯人关在一起的。但是这样势必会造成死刑犯压力巨大。因此这些年，一般只设立重刑号，死刑犯和普通犯在一个监室，而且<strong>直到行刑前头一天晚上或者马上执行死刑的早上才会通知犯人即将执行</strong>。这也是人文关怀的一个方面。&quot;——重刑号混关＋延迟告知，是全书制度的底座。</li><li><strong>黑话体系</strong>：行刑＝&quot;<strong>上路</strong>&quot;，被枪毙＝&quot;<strong>吃花生米</strong>&quot;；问最后一餐＝问&quot;<strong>断头饭</strong>&quot;，是看守所公认最难开口的差事——&quot;大多数死囚是不愿意回答这个问题的，因为他们根本不愿意接受自己的生命即将结束这个事实&quot;。</li><li><strong>最后一夜的程序</strong>：管教（或受托的狱友/班长）询问断头饭想吃什么——帖中死囚要&quot;煎饼卷土豆丝就鸡蛋汤&quot;、退而求&quot;一碗白米饭炒个茄子&quot;、或&quot;上车饺子下车面&quot;要饺子、或面条；可讨<strong>二两白酒</strong>；接受死囚<strong>器官捐献</strong>登记（家属以&quot;赎罪&quot;相劝）；临刑前脚镣加重（&quot;被宣判了死刑的人就会[上重镣]&quot;），遗书、上诉书常由号中识字者代笔。</li><li><strong>监号内的规矩</strong>：&quot;凡是因为要执行死刑而改善的伙食<strong>都要第一个给即将上路的人吃</strong>——毕竟这碗饭是以死一些人而作为代价换来的&quot;；行刑当日&quot;为了干净点上路&quot;，要&quot;把裤腿绑上&quot;防大小便失禁；二审裁定下来家属即送新衣（送衣几乎等于宣告结局）；临刑者彻夜未眠，有人反复点烟、一小口一小口喝可乐。</li><li><strong>司法复核程序</strong>：行刑当天由法官、检察官、法警到场，武警押解，在开放提审室逐一宣读；帖 136 写了复核不核准的情形——最高人民法院&quot;本着<strong>疑案不杀</strong>的精神，没有批准 L 市中级人民法院对你的死刑宣判。你的案子将在接下来的一段时间内重新审理&quot;（发回重审）。</li><li><strong>成色</strong>：整个链条＝【行业·真实】（作者以出版为目的做过核实，死刑复核、发回重审、临刑告知均与公开司法制度吻合）；具体人物故事＝【小说·演绎】。这是 14 部里&quot;知识密度&quot;最高、最可直接引用的一帖。</li></ul><h3 id="a11-dna-亲子鉴定的实际流程-帖-49" tabindex="-1">A11. DNA 亲子鉴定的实际流程（帖 49） <a class="header-anchor" href="#a11-dna-亲子鉴定的实际流程-帖-49" aria-label="Permalink to &quot;A11. DNA 亲子鉴定的实际流程（帖 49）&quot;">​</a></h3><ul><li><strong>行业史</strong>：&quot;2002 年 5 月国家将 DNA 亲子鉴定等项目向第三方鉴定机构开放，第二年我母亲就从事了这个行业，是中国最早的一批 DNA 鉴定师。&quot;</li><li><strong>两分法</strong>（帖 49 论战式科普，最有引用价值）：<strong>司法亲子鉴定</strong>——&quot;程序非常非常严，既要本人到现场，又需要专业采样人员亲自采样，而且采样过程要拍照留证，鉴定结果出来要有 2 名以上鉴定师的签字，这样做出来的报告才具有法律效力&quot;；<strong>个人隐私亲子鉴定</strong>——&quot;只需要提供检材……不需要委托人出示证件，甚至可以用化名进行，只提供给委托人参考，所以也就没有法律效力&quot;，机构&quot;只对鉴定结果的准确性负责，无法对检材的出处负责&quot;。</li><li><strong>样本学</strong>：毛发须带毛囊，&quot;几乎所有的鉴定机构要求的只是<strong>五根左右</strong>就够了&quot;（网传 15-20 根为讹传）；烟蒂（含唾沫）、吃过的口香糖、指甲、血痕均可。</li><li><strong>行业数据</strong>：十年经手委托一万余件，&quot;排除&quot;结果常年维持在 26%～29%——&quot;每 4 个来做亲子鉴定的，就有一个是&#39;非亲生&#39;的&quot;；行业还有<strong>加急鉴定</strong>一档，当天出结果，是故事里的高频戏剧支点。</li><li><strong>成色</strong>：全部＝【行业·真实】（流程、数据与公开的司法鉴定规范一致）；由此衍生的换子、假样本敲诈故事＝【小说·演绎】。</li></ul><h3 id="a12-法医学常识-帖-18" tabindex="-1">A12. 法医学常识（帖 18） <a class="header-anchor" href="#a12-法医学常识-帖-18" aria-label="Permalink to &quot;A12. 法医学常识（帖 18）&quot;">​</a></h3><ul><li><strong>尸斑定移动</strong>：&quot;尸体仰面躺着，尸斑才会出现在背部&quot;——水塔男尸&quot;背部有尸斑，这说明尸体被移动过&quot;。</li><li><strong>死亡时间推断</strong>：以尸体现象与温度统计推断（帖中两例：死亡约 5 天、约 7 天）。</li><li><strong>尸体痉挛</strong>：帖 18 特意科普——&quot;尸体痉挛一般不经过肌肉弛缓阶段而一直持续到正常尸僵的出现&quot;，能把肢体固定在临死瞬间的姿势，故某些&quot;死状&quot;本身就是遗言。</li><li><strong>成色</strong>：以上均为法医学教科书内容＝【行业·真实】；特案组建制与案件＝【小说·演绎】（作者声明&quot;本文根据真实案件改编，涉案地名人名均为化名&quot;）。</li></ul><h3 id="a13-心理学知识-帖-27" tabindex="-1">A13. 心理学知识（帖 27） <a class="header-anchor" href="#a13-心理学知识-帖-27" aria-label="Permalink to &quot;A13. 心理学知识（帖 27）&quot;">​</a></h3><ul><li><strong>病名与症状</strong>：社交恐惧症（满脸痤疮少年的自卑路径：惧目光→&quot;害羞膀胱&quot;→惧蚊帐气流→&quot;无限恐惧症&quot;，&quot;甚至害怕气流在我的世界里出现，就算只是一丝丝微风或者身边人对我说话时候的呼气&quot;）。</li><li><strong>防御机制</strong>：&quot;防御机制有一百零一种，其中有一种就是叫做&#39;否定&#39;……我在否定一部分事实的存在，为了让自己不至于崩塌。&quot;理论底座是弗洛伊德的本我—超我—外部世界三重压力产生焦虑。</li><li><strong>成色</strong>：恐惧症谱系、防御机制分类＝【行业·真实】（&quot;101 种&quot;是作者对防御机制清单的文学化计数，教科书通常列十余种主要机制，引用时需注意）；邱凌的&quot;镜像人格&quot;犯罪＝【小说·演绎】。</li></ul><h3 id="a14-灵异档案的-官方化-设定-帖-140、24、141" tabindex="-1">A14. 灵异档案的&quot;官方化&quot;设定（帖 140、24、141） <a class="header-anchor" href="#a14-灵异档案的-官方化-设定-帖-140、24、141" aria-label="Permalink to &quot;A14. 灵异档案的&quot;官方化&quot;设定（帖 140、24、141）&quot;">​</a></h3><ul><li><strong>名词表式世界观</strong>（帖 140）：作者在结尾附全套名词表——太岁/王太岁（穿越奇点的寄生体）、主脑、通道（三处，第一通道毁于 1976 年唐山大地震）、奇点、平行世界、始原体、关联控制/最终控制、神山（&quot;公元 117 年成立&quot;的全球组织，中国区分 1-8 局渗透政府部门）、深井（神山内部反叛组织）。手法要义：<strong>用词典体给幻想立法</strong>。</li><li><strong>衙门型机构</strong>（帖 24）：民调局专管民俗宗教异事；魂魄体系写实到可推理——&quot;她的一魂二魄已经消失，就算要轮回转世，也不能再世为人，只怕要转投畜道&quot;（三魂七魄损耗的会计学）。</li><li><strong>成色</strong>：三魂七魄、轮回＝【民俗·传说】；以上机构与名词＝【小说·演绎】，但唐山大地震、大兴安岭大火（帖 24 楔子）等年代锚点是【真实】。</li></ul><hr><h2 id="b-志怪叙事的知识——这类帖子怎么写" tabindex="-1">B. 志怪叙事的知识——这类帖子怎么写 <a class="header-anchor" href="#b-志怪叙事的知识——这类帖子怎么写" aria-label="Permalink to &quot;B. 志怪叙事的知识——这类帖子怎么写&quot;">​</a></h2><h3 id="b1-五大配方逐条展开" tabindex="-1">B1. 五大配方逐条展开 <a class="header-anchor" href="#b1-五大配方逐条展开" aria-label="Permalink to &quot;B1. 五大配方逐条展开&quot;">​</a></h3><p><strong>配方一：钩子楔子——&quot;先给你看一样不该存在的东西&quot;。</strong> 操作要点：把最反常的画面放进正文之前，且<strong>不解释</strong>。钩子最好是一件&quot;物&quot;或一具&quot;尸&quot;：半部焚余的《青囊经》（帖 119）、风陵渡被弃的女婴（帖 206）、枪打不死的獠牙怪尸（帖 24）、当众褪尽手铐脚镣的贼（帖 26）、五具尸体拼成的雪人（帖 18）、颈上缝线的少女（帖 110）。楔子的信息量要控制在&quot;我知道这里不对，但我不知道为什么&quot;——解释权留给后文，追读动力就来自这笔债。</p><p><strong>配方二：短怪谈铺垫长主线——&quot;先卖几个真的，再卖一个大的&quot;。</strong> 操作要点：先连发 3-8 篇本地短怪谈，建立&quot;叙事人可信度&quot;，再让主线人物从短篇里自然长出来。帖 146 是范本：冥币的士司机、魏瞎子断死期、坟头打笳乐——三个短篇之后，&quot;我&quot;已被怪事缠身，主线人物王八、娟娟登场就不突兀；帖 27 用《残肢》《肉》等病人序曲先立&quot;变态档案&quot;，再引出邱凌；帖 49 用 A 男、C 女、D 女三个短案养号，再抛泰国邪教长线。短篇与主线之间要有一根&quot;牵丝&quot;：同一个地点、同一句谶语、同一个人名。</p><p><strong>配方三：神秘机构/传承体系——&quot;给怪事一个建制&quot;。</strong> 操作要点：衙门型（民调局，帖 24）、公司型（观察者心理咨询事务所，帖 27；鉴定中心，帖 49）、学院型（云霄学院，帖 141、142）、家族型（御灵蒋家、相术陈家，帖 121；五行贼王世家，帖 26）、秘密结社型（神山/深井，帖 140）。机构化的三重作用：怪事<strong>可被管理</strong>（有人负责，读者才信没人上报）、<strong>可被继承</strong>（师承/家传给续集留种）、<strong>可被保密</strong>（&quot;以上笔录已经看过&quot;式的档案腔天然带权威）。机构最好带一个&quot;编制内异人&quot;：吴仁荻身中七钉不死（帖 24）、老席守着僵尸分级表（帖 141）。</p><p><strong>配方四：知识密度护城河——&quot;让内行挑不出错，外行看得入迷&quot;。</strong> 操作要点：选一个行业，把<strong>行话、流程、数字</strong>写进情节而非注释。数字最提神：排除率 26%～29%、十年一万余件（帖 49）；汉墓深二十米以上、地下 22 米空洞（帖 141）；&quot;每隔七八尺一个&quot;草绳串尸（帖 110）；死亡时间约 5 天、7 天（帖 18）。流程次之：司法/隐私鉴定两分法、断头饭询问、最高法复核宣读。行话最后：春典对答、老荣的斜眼、&quot;上路&quot;&quot;吃花生米&quot;。检验标准：把小说删掉只留知识，这段话还能当科普读——帖 136、49、141 均过关。</p><p><strong>配方五：人性兜底——&quot;邪到最后，收在人心&quot;。</strong> 操作要点：每条邪线留一个&quot;人心的解释&quot;或&quot;人情的落点&quot;。杨枭收魂是为了亡妻（帖 24）；断头饭的&quot;上车饺子下车面&quot;（帖 136）；陈大姐母女在养老院重逢，而妹妹&quot;到现在还没有任何消息&quot;——&quot;我写的不是小说，没办法给大家一个圆满的结局&quot;（帖 49）；六相后记自陈&quot;所有的正面人物，主角一个不会死&quot;，并统计哭 316 条、笑 328 条（帖 121）。兜底不是洗白罪行，而是给读者一个&quot;读完不冷&quot;的出口。</p><h3 id="b2-真实感四来源——操作要点" tabindex="-1">B2. 真实感四来源——操作要点 <a class="header-anchor" href="#b2-真实感四来源——操作要点" aria-label="Permalink to &quot;B2. 真实感四来源——操作要点&quot;">​</a></h3><p><strong>来源一：亲历型叙事人。<strong>身份要具体到&quot;工种＋年限＋一桩拿不上台面的旧事&quot;：化工专业毕业、在三峡商场当三年保安（帖 146）；法医学毕业、母亲是 2003 年第一批入行者（帖 49）；重刑号服刑 18 个月、写下三十万字杂记（帖 136）。叙事人还要有</strong>职业性节制</strong>：不轻易信鬼，先找物证——&quot;打笳乐的声音存在是有可能的，但不见得就是跟鬼怪[有关]&quot;（帖 146）；警察捡到隧道里的手机，先问&quot;手机的主人，现在哪里呢？&quot;（帖 18）。先祛魅后见魅，鬼才有分量。</p><p>**来源二：真实坐标。**街道级地名＋方言＋物价：港窑路、磨盘、318 国道、&quot;麻木&quot;&quot;日白&quot;（帖 146）；朝内凶宅（帖 24）；从赃款里&quot;拿出来 150 块钱&quot;买水买面买烟（帖 136）。坐标越细，鬼越可信——灵异发生在&quot;你家楼下那条没名字的巷子&quot;时，读者无处可逃。</p><p><strong>来源三：真新闻嫁接。<strong>把虚构线头缝进公共记忆：大兴安岭 1987（帖 24 楔子）、唐山大地震毁第一通道（帖 140）、&quot;东北二王&quot;悬赏通缉史并附注释（帖 49）、三峡蓄水永埋疑冢（帖 141）、县长日记体（帖 18）。嫁接要领：新闻只提供</strong>时间与地名</strong>，不篡改事件本体，怪事长在新闻的缝隙里。</p><p><strong>来源四：连载元直播。<strong>报更时间、答读者问、防山寨声明、谈出版进度——&quot;本人在天涯只有一个 ID&quot;&quot;每天只更新两次&quot;（帖 136）；&quot;出版物是一个阉割版本，网上所有的电子版本全部是阉割版&quot;（帖 140）；&quot;书名改成了《异事录》&quot;（帖 146）；购书送读书贝、加公众号（帖 49）。元直播让读者从旁观者变成</strong>见证人</strong>：&quot;我看着它从帖子变成铅字&quot;，这种陪伴感是天涯灵异区别于普通网文的独特资产。</p><h3 id="b3-名著用招对照表-●强用-◐弱用-—不用" tabindex="-1">B3. 名著用招对照表（●强用 ◐弱用 —不用） <a class="header-anchor" href="#b3-名著用招对照表-●强用-◐弱用-—不用" aria-label="Permalink to &quot;B3. 名著用招对照表（●强用 ◐弱用 —不用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>帖号/书名</th><th>钩子楔子</th><th>短怪谈铺垫</th><th>机构体系</th><th>知识密度</th><th>人性兜底</th><th>亲历叙事</th><th>真实坐标</th><th>新闻嫁接</th><th>元直播</th></tr></thead><tbody><tr><td>119 青囊尸衣</td><td>●</td><td>—</td><td>●</td><td>●</td><td>●</td><td>◐</td><td>●</td><td>◐</td><td>●</td></tr><tr><td>206 鬼壶</td><td>●</td><td>—</td><td>●</td><td>●</td><td>●</td><td>◐</td><td>●</td><td>—</td><td>●</td></tr><tr><td>146 宜昌鬼事</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td></tr><tr><td>132 密道追踪</td><td>●</td><td>●</td><td>◐</td><td>●</td><td>●</td><td>●</td><td>●</td><td>—</td><td>●</td></tr><tr><td>140 冒死记录</td><td>●</td><td>—</td><td>●</td><td>●</td><td>●</td><td>◐</td><td>◐</td><td>●</td><td>●</td></tr><tr><td>24 民调局异闻录</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>◐</td><td>●</td><td>●</td><td>●</td></tr><tr><td>26 五大贼王</td><td>●</td><td>—</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td></tr><tr><td>18 十宗罪5</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td></tr><tr><td>49 DNA鉴定师</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td></tr><tr><td>27 心理大师</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>—</td><td>●</td></tr><tr><td>117 戚绝书</td><td>●</td><td>—</td><td>●</td><td>●</td><td>●</td><td>—</td><td>●</td><td>●</td><td>●</td></tr><tr><td>121 六相</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td></tr><tr><td>142 采药师</td><td>●</td><td>—</td><td>●</td><td>◐</td><td>●</td><td>—</td><td>—</td><td>—</td><td>●</td></tr><tr><td>136 死刑犯</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>●</td><td>—</td><td>●</td></tr></tbody></table><p><strong>用法提示</strong>：九项全 ● 的帖子（146、49、18）正是天涯灵异文的&quot;满配模板&quot;；第三人称奇幻（142）天生缺亲历与坐标两招，靠知识密度（中药注释）与人性兜底补位；民国/明代背景（26、117）以&quot;新闻嫁接&quot;换成&quot;正史嫁接&quot;（张作霖、戚继光），机制相同。</p><hr><p><em>本库全部条目出自原文，未混入外部资料；引用原句以引号标出，可直接回查对应帖号。</em></p>',50)])])}const b=o(d,[["render",n]]);export{h as __pageData,b as default};
